#import <XCTest/XCTest.h>
#import "PepperDualJumpNoiseXORCipher.hpp"
#import "PrintExamplesHelper.hpp"
#import "CipherGauntlet.hpp"
#include <memory>

@interface Battery_PepperDualJumpNoiseXORCipher : XCTestCase

@end

@implementation Battery_PepperDualJumpNoiseXORCipher

- (void)test_gauntlet_PepperDualJumpNoiseXORCipher {
    static std::uint8_t aAllZero[SOCCER_BLOCK_SIZE];
    static std::uint8_t aAllOne[SOCCER_BLOCK_SIZE];
    static std::uint8_t aRandA[SOCCER_BLOCK_SIZE];
    static std::uint8_t aRandB[SOCCER_BLOCK_SIZE];
    static std::uint8_t aRandC[SOCCER_BLOCK_SIZE];
    static std::uint8_t aRandD[SOCCER_BLOCK_SIZE];
    
    CipherGauntlet::ArrayZero(aAllZero, SOCCER_BLOCK_SIZE);
    CipherGauntlet::ArrayOne(aAllOne, SOCCER_BLOCK_SIZE);
    CipherGauntlet::ArrayRandomize(aRandA, SOCCER_BLOCK_SIZE);
    CipherGauntlet::ArrayRandomize(aRandB, SOCCER_BLOCK_SIZE);
    CipherGauntlet::ArrayRandomize(aRandC, SOCCER_BLOCK_SIZE);
    CipherGauntlet::ArrayRandomize(aRandD, SOCCER_BLOCK_SIZE);
    
    std::vector<std::uint8_t *> aListMask;
    std::vector<std::uint8_t *> aListNoise;
    std::vector<std::uint8_t *> aListMaskJumps;
    std::vector<std::uint8_t *> aListNoiseJumps;
    
    aListMask.push_back(aRandA); aListMask.push_back(aRandB); aListMask.push_back(aRandC); aListMask.push_back(aRandD);
    aListMask.push_back(aAllZero); aListMask.push_back(aAllOne);
    
    aListNoise.push_back(aRandA); aListNoise.push_back(aRandB); aListNoise.push_back(aRandC); aListNoise.push_back(aRandD);
    aListNoise.push_back(aAllZero); aListNoise.push_back(aAllOne);
    
    aListMaskJumps.push_back(aRandA); aListMaskJumps.push_back(aRandB); aListMaskJumps.push_back(aRandC); aListMaskJumps.push_back(aRandD);
    aListMaskJumps.push_back(aAllZero); aListMaskJumps.push_back(aAllOne);
    
    aListNoiseJumps.push_back(aRandA); aListNoiseJumps.push_back(aRandB); aListNoiseJumps.push_back(aRandC); aListNoiseJumps.push_back(aRandD);
    aListNoiseJumps.push_back(aAllZero); aListNoiseJumps.push_back(aAllOne);
    
    static CipherGauntlet aGauntlet;
    
    for (std::size_t aIndexA=0; aIndexA<aListMask.size(); aIndexA++) {
        std::uint8_t *aMask = aListMask[aIndexA];
        for (std::size_t aIndexB=0; aIndexB<aListNoise.size(); aIndexB++) {
            std::uint8_t *aNoise = aListNoise[aIndexB];
            for (std::size_t aIndexC=0; aIndexC<aListMaskJumps.size(); aIndexC++) {
                std::uint8_t *aMaskJumps = aListMaskJumps[aIndexC];
                for (std::size_t aIndexD=0; aIndexD<aListNoiseJumps.size(); aIndexD++) {
                    std::uint8_t *aNoiseJumps = aListNoiseJumps[aIndexD];
                    PepperDualJumpNoiseXORCipher aCipher(aMask,
                                                         aNoise,
                                                         aMaskJumps,
                                                         aNoiseJumps);
                    if (!aGauntlet.RunCipher(&aCipher,
                                             16,
                                             "PepperDualJumpNoiseXORCipher")) {
                        XCTFail("[PepperDualJumpNoiseXORCipher] test_gauntlet_PepperDualJumpNoiseXORCipher failed.");
                        return;
                    }
                }
            }
        }
    }
}

- (void)test_fixed_16_A_PepperDualJumpNoiseXORCipher {

    // Before Cipher:
    // bit0 00000000  00000000
    // bit1 00000000  00000000
    // bit2 00000000  00000000
    // bit3 00000000  00000000
    // bit4 00000000  00000000
    // bit5 00000000  00000000
    // bit6 00000000  00000000
    // bit7 00000000  00000000
    //
    // After Cipher:
    // bit0 10100111  11100000
    // bit1 00100100  11011000
    // bit2 10011000  11101011
    // bit3 11010100  01001010
    // bit4 10100011  00101100
    // bit5 01111001  10111100
    // bit6 00000010  01001111
    // bit7 11111101  00011110
    //
    // Avalanche:
    // bit0 X.X..XXX  XXX.....
    // bit1 ..X..X..  XX.XX...
    // bit2 X..XX...  XXX.X.XX
    // bit3 XX.X.X..  .X..X.X.
    // bit4 X.X...XX  ..X.XX..
    // bit5 .XXXX..X  X.XXXX..
    // bit6 ......X.  .X..XXXX
    // bit7 XXXXXX.X  ...XXXX.
    // Avalanche: 50.00%

    const std::uint8_t aOriginal[16] = {
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    };

    const std::uint8_t aMaskBuffer[16] = {
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    };

    const std::uint8_t aNoiseBuffer[16] = {
        0xB9, 0x15, 0xCD, 0x35, 0x25, 0xD1, 0x8A, 0x8D, 0xE4, 0xF2, 0xAC, 0x45, 0x7F, 0x0F, 0x33, 0x22
    };

    const std::uint8_t aMaskJumpBuffer[16] = {
        0x57, 0x44, 0x7A, 0xDE, 0x4D, 0x85, 0x19, 0xBE, 0x7E, 0x74, 0x7F, 0xDA, 0x60, 0x31, 0x3A, 0xCD
    };

    const std::uint8_t aNoiseJumpBuffer[16] = {
        0xCA, 0xB1, 0x06, 0xF7, 0xDF, 0x79, 0x38, 0x99, 0x22, 0x2C, 0x2B, 0x23, 0x70, 0xBE, 0xD4, 0x25
    };

    PepperDualJumpNoiseXORCipher aCrypt(aMaskBuffer,
        aNoiseBuffer,
        aMaskJumpBuffer,
        aNoiseJumpBuffer);

    const std::uint8_t aExpected[16] = {
        0xB9, 0x15, 0xCD, 0x35, 0x25, 0xD1, 0x8A, 0x8D, 0xE4, 0xF2, 0xAC, 0x45, 0x7F, 0x0F, 0x33, 0x22
    };

    std::uint8_t aWorker[sizeof(aOriginal)] = {};
    std::uint8_t aEncrypted[sizeof(aOriginal)] = {};
    std::uint8_t aUnencrypted[sizeof(aOriginal)] = {};

    if (!CipherGauntlet::SealDataExpectingSuccess(aOriginal,
                                                    aWorker,
                                                    aEncrypted,
                                                    sizeof(aOriginal),
                                                    &aCrypt,
                                                    "test_fixed_16_A_PepperDualJumpNoiseXORCipher")) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_16_A_PepperDualJumpNoiseXORCipher failed while sealing.");
        return;
    }

    if (!CipherGauntlet::Matches(aExpected, aEncrypted, sizeof(aExpected))) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_16_A_PepperDualJumpNoiseXORCipher failed after seal.");
        printf("Expected: %s\n", PrintExamplesHelper::HexArray(aExpected, sizeof(aExpected)).c_str());
        printf("Actual: %s\n", PrintExamplesHelper::HexArray(aEncrypted, sizeof(aEncrypted)).c_str());
        return;
    }

    if (!CipherGauntlet::UnsealDataExpectingSuccess(aEncrypted,
                                                      aWorker,
                                                      aUnencrypted,
                                                      sizeof(aEncrypted),
                                                      &aCrypt,
                                                      "test_fixed_16_A_PepperDualJumpNoiseXORCipher")) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_16_A_PepperDualJumpNoiseXORCipher failed while unsealing.");
        return;
    }

    if (!CipherGauntlet::Matches(aOriginal, aUnencrypted, sizeof(aOriginal))) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_16_A_PepperDualJumpNoiseXORCipher failed after unseal.");
        printf("Expected: %s\n", PrintExamplesHelper::HexArray(aOriginal, sizeof(aOriginal)).c_str());
        printf("Actual: %s\n", PrintExamplesHelper::HexArray(aUnencrypted, sizeof(aUnencrypted)).c_str());
        return;
    }

}

- (void)test_fixed_16_B_PepperDualJumpNoiseXORCipher {

    // Before Cipher:
    // bit0 11111111  11111111
    // bit1 11111111  11111111
    // bit2 11111111  11111111
    // bit3 11111111  11111111
    // bit4 11111111  11111111
    // bit5 11111111  11111111
    // bit6 11111111  11111111
    // bit7 11111111  11111111
    //
    // After Cipher:
    // bit0 00011110  00000111
    // bit1 01100110  01001001
    // bit2 01101000  10001111
    // bit3 10110101  11110110
    // bit4 11010000  11110111
    // bit5 01010100  01100100
    // bit6 11110001  10111011
    // bit7 01101011  11100011
    //
    // Avalanche:
    // bit0 XXX....X  XXXXX...
    // bit1 X..XX..X  X.XX.XX.
    // bit2 X..X.XXX  .XXX....
    // bit3 .X..X.X.  ....X..X
    // bit4 ..X.XXXX  ....X...
    // bit5 X.X.X.XX  X..XX.XX
    // bit6 ....XXX.  .X...X..
    // bit7 X..X.X..  ...XXX..
    // Avalanche: 45.31%

    const std::uint8_t aOriginal[16] = {
        0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF
    };

    const std::uint8_t aMaskBuffer[16] = {
        0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF
    };

    const std::uint8_t aNoiseBuffer[16] = {
        0x1A, 0x6F, 0x73, 0x9E, 0xA1, 0xD4, 0xC1, 0x13, 0x3B, 0x5D, 0x1F, 0x1A, 0x62, 0xBC, 0xBB, 0xEB
    };

    const std::uint8_t aMaskJumpBuffer[16] = {
        0xDE, 0x3D, 0x0D, 0x5B, 0x98, 0x88, 0xAC, 0x60, 0xAC, 0x1B, 0x82, 0x65, 0xCA, 0x42, 0x5C, 0x27
    };

    const std::uint8_t aNoiseJumpBuffer[16] = {
        0x95, 0xB4, 0x30, 0xE4, 0x41, 0x72, 0xA2, 0x8E, 0x83, 0x97, 0xAC, 0x88, 0xB7, 0x5A, 0xBC, 0xFF
    };

    PepperDualJumpNoiseXORCipher aCrypt(aMaskBuffer,
        aNoiseBuffer,
        aMaskJumpBuffer,
        aNoiseJumpBuffer);

    const std::uint8_t aExpected[16] = {
        0x1A, 0x6F, 0x73, 0x9E, 0xA1, 0xD4, 0xC1, 0x13, 0x3B, 0x5D, 0x1F, 0x1A, 0x62, 0xBC, 0xBB, 0xEB
    };

    std::uint8_t aWorker[sizeof(aOriginal)] = {};
    std::uint8_t aEncrypted[sizeof(aOriginal)] = {};
    std::uint8_t aUnencrypted[sizeof(aOriginal)] = {};

    if (!CipherGauntlet::SealDataExpectingSuccess(aOriginal,
                                                    aWorker,
                                                    aEncrypted,
                                                    sizeof(aOriginal),
                                                    &aCrypt,
                                                    "test_fixed_16_B_PepperDualJumpNoiseXORCipher")) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_16_B_PepperDualJumpNoiseXORCipher failed while sealing.");
        return;
    }

    if (!CipherGauntlet::Matches(aExpected, aEncrypted, sizeof(aExpected))) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_16_B_PepperDualJumpNoiseXORCipher failed after seal.");
        printf("Expected: %s\n", PrintExamplesHelper::HexArray(aExpected, sizeof(aExpected)).c_str());
        printf("Actual: %s\n", PrintExamplesHelper::HexArray(aEncrypted, sizeof(aEncrypted)).c_str());
        return;
    }

    if (!CipherGauntlet::UnsealDataExpectingSuccess(aEncrypted,
                                                      aWorker,
                                                      aUnencrypted,
                                                      sizeof(aEncrypted),
                                                      &aCrypt,
                                                      "test_fixed_16_B_PepperDualJumpNoiseXORCipher")) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_16_B_PepperDualJumpNoiseXORCipher failed while unsealing.");
        return;
    }

    if (!CipherGauntlet::Matches(aOriginal, aUnencrypted, sizeof(aOriginal))) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_16_B_PepperDualJumpNoiseXORCipher failed after unseal.");
        printf("Expected: %s\n", PrintExamplesHelper::HexArray(aOriginal, sizeof(aOriginal)).c_str());
        printf("Actual: %s\n", PrintExamplesHelper::HexArray(aUnencrypted, sizeof(aUnencrypted)).c_str());
        return;
    }

}

- (void)test_fixed_16_C_PepperDualJumpNoiseXORCipher {

    // Before Cipher:
    // bit0 10101010  10101010
    // bit1 10101010  10101010
    // bit2 10101010  10101010
    // bit3 10101010  10101010
    // bit4 01010101  01010101
    // bit5 01010101  01010101
    // bit6 01010101  01010101
    // bit7 01010101  01010101
    //
    // After Cipher:
    // bit0 01111100  10000101
    // bit1 11110110  10100111
    // bit2 01100110  01100010
    // bit3 10100110  11101100
    // bit4 00100101  11011011
    // bit5 11110001  10011100
    // bit6 00001110  00111100
    // bit7 10001010  01110001
    //
    // Avalanche:
    // bit0 XX.X.XX.  ..X.XXXX
    // bit1 .X.XXX..  ....XX.X
    // bit2 XX..XX..  XX..X...
    // bit3 ....XX..  .X...XX.
    // bit4 .XXX....  X...XXX.
    // bit5 X.X..X..  XX..X..X
    // bit6 .X.XX.XX  .XX.X..X
    // bit7 XX.XXXXX  ..X..X..
    // Avalanche: 47.66%

    const std::uint8_t aOriginal[16] = {
        0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F
    };

    const std::uint8_t aMaskBuffer[16] = {
        0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F
    };

    const std::uint8_t aNoiseBuffer[16] = {
        0x55, 0xE4, 0xFC, 0xC4, 0x83, 0xFA, 0x73, 0x0C, 0xDC, 0x39, 0x73, 0x0F, 0x1E, 0xD6, 0x68, 0xC9
    };

    const std::uint8_t aMaskJumpBuffer[16] = {
        0x38, 0x69, 0x0B, 0x8E, 0xE1, 0x4D, 0xB8, 0x8A, 0xA3, 0x9B, 0x4E, 0x61, 0x0F, 0x93, 0x72, 0x8B
    };

    const std::uint8_t aNoiseJumpBuffer[16] = {
        0x98, 0xBF, 0xCD, 0x80, 0x45, 0xF4, 0xAE, 0x86, 0x86, 0x2B, 0x03, 0x38, 0x18, 0x4D, 0x03, 0x01
    };

    PepperDualJumpNoiseXORCipher aCrypt(aMaskBuffer,
        aNoiseBuffer,
        aMaskJumpBuffer,
        aNoiseJumpBuffer);

    const std::uint8_t aExpected[16] = {
        0x55, 0xE4, 0xFC, 0xC4, 0x83, 0xFA, 0x73, 0x0C, 0xDC, 0x39, 0x73, 0x0F, 0x1E, 0xD6, 0x68, 0xC9
    };

    std::uint8_t aWorker[sizeof(aOriginal)] = {};
    std::uint8_t aEncrypted[sizeof(aOriginal)] = {};
    std::uint8_t aUnencrypted[sizeof(aOriginal)] = {};

    if (!CipherGauntlet::SealDataExpectingSuccess(aOriginal,
                                                    aWorker,
                                                    aEncrypted,
                                                    sizeof(aOriginal),
                                                    &aCrypt,
                                                    "test_fixed_16_C_PepperDualJumpNoiseXORCipher")) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_16_C_PepperDualJumpNoiseXORCipher failed while sealing.");
        return;
    }

    if (!CipherGauntlet::Matches(aExpected, aEncrypted, sizeof(aExpected))) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_16_C_PepperDualJumpNoiseXORCipher failed after seal.");
        printf("Expected: %s\n", PrintExamplesHelper::HexArray(aExpected, sizeof(aExpected)).c_str());
        printf("Actual: %s\n", PrintExamplesHelper::HexArray(aEncrypted, sizeof(aEncrypted)).c_str());
        return;
    }

    if (!CipherGauntlet::UnsealDataExpectingSuccess(aEncrypted,
                                                      aWorker,
                                                      aUnencrypted,
                                                      sizeof(aEncrypted),
                                                      &aCrypt,
                                                      "test_fixed_16_C_PepperDualJumpNoiseXORCipher")) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_16_C_PepperDualJumpNoiseXORCipher failed while unsealing.");
        return;
    }

    if (!CipherGauntlet::Matches(aOriginal, aUnencrypted, sizeof(aOriginal))) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_16_C_PepperDualJumpNoiseXORCipher failed after unseal.");
        printf("Expected: %s\n", PrintExamplesHelper::HexArray(aOriginal, sizeof(aOriginal)).c_str());
        printf("Actual: %s\n", PrintExamplesHelper::HexArray(aUnencrypted, sizeof(aUnencrypted)).c_str());
        return;
    }

}

- (void)test_fixed_16_D_PepperDualJumpNoiseXORCipher {

    // Before Cipher:
    // bit0 10101010  10101010
    // bit1 10101010  10101010
    // bit2 01010101  01010101
    // bit3 01010101  01010101
    // bit4 10101010  10101010
    // bit5 10101010  10101010
    // bit6 01010101  01010101
    // bit7 01010101  01010101
    //
    // After Cipher:
    // bit0 10101010  01101000
    // bit1 11000010  01011101
    // bit2 11110110  10100000
    // bit3 11101001  00001000
    // bit4 01001001  11010010
    // bit5 00001100  01000000
    // bit6 10111101  11110100
    // bit7 10110110  10110100
    //
    // Avalanche:
    // bit0 ........  XX....X.
    // bit1 .XX.X...  XXXX.XXX
    // bit2 X.X...XX  XXXX.X.X
    // bit3 X.XXXX..  .X.XXX.X
    // bit4 XXX...XX  .XXXX...
    // bit5 X.X..XX.  XXX.X.X.
    // bit6 XXX.X...  X.X....X
    // bit7 XXX...XX  XXX....X
    // Avalanche: 52.34%

    const std::uint8_t aOriginal[16] = {
        0xCC, 0x33, 0xCC, 0x33, 0xCC, 0x33, 0xCC, 0x33, 0xCC, 0x33, 0xCC, 0x33, 0xCC, 0x33, 0xCC, 0x33
    };

    const std::uint8_t aMaskBuffer[16] = {
        0xCC, 0x33, 0xCC, 0x33, 0xCC, 0x33, 0xCC, 0x33, 0xCC, 0x33, 0xCC, 0x33, 0xCC, 0x33, 0xCC, 0x33
    };

    const std::uint8_t aNoiseBuffer[16] = {
        0xF3, 0x78, 0xB3, 0x23, 0x9E, 0x27, 0xE1, 0x1A, 0x2B, 0xCE, 0xA3, 0x4B, 0xD0, 0x43, 0x08, 0x40
    };

    const std::uint8_t aMaskJumpBuffer[16] = {
        0x9F, 0x6E, 0x68, 0xF8, 0xE7, 0x30, 0x23, 0x1C, 0xE0, 0xE1, 0xA3, 0xC7, 0x5B, 0xFF, 0x70, 0x43
    };

    const std::uint8_t aNoiseJumpBuffer[16] = {
        0x80, 0xE7, 0x48, 0x37, 0x0E, 0x73, 0xD4, 0x86, 0x2E, 0xFC, 0x9E, 0x6D, 0x0E, 0x05, 0x9A, 0x37
    };

    PepperDualJumpNoiseXORCipher aCrypt(aMaskBuffer,
        aNoiseBuffer,
        aMaskJumpBuffer,
        aNoiseJumpBuffer);

    const std::uint8_t aExpected[16] = {
        0xF3, 0x78, 0xB3, 0x23, 0x9E, 0x27, 0xE1, 0x1A, 0x2B, 0xCE, 0xA3, 0x4B, 0xD0, 0x43, 0x08, 0x40
    };

    std::uint8_t aWorker[sizeof(aOriginal)] = {};
    std::uint8_t aEncrypted[sizeof(aOriginal)] = {};
    std::uint8_t aUnencrypted[sizeof(aOriginal)] = {};

    if (!CipherGauntlet::SealDataExpectingSuccess(aOriginal,
                                                    aWorker,
                                                    aEncrypted,
                                                    sizeof(aOriginal),
                                                    &aCrypt,
                                                    "test_fixed_16_D_PepperDualJumpNoiseXORCipher")) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_16_D_PepperDualJumpNoiseXORCipher failed while sealing.");
        return;
    }

    if (!CipherGauntlet::Matches(aExpected, aEncrypted, sizeof(aExpected))) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_16_D_PepperDualJumpNoiseXORCipher failed after seal.");
        printf("Expected: %s\n", PrintExamplesHelper::HexArray(aExpected, sizeof(aExpected)).c_str());
        printf("Actual: %s\n", PrintExamplesHelper::HexArray(aEncrypted, sizeof(aEncrypted)).c_str());
        return;
    }

    if (!CipherGauntlet::UnsealDataExpectingSuccess(aEncrypted,
                                                      aWorker,
                                                      aUnencrypted,
                                                      sizeof(aEncrypted),
                                                      &aCrypt,
                                                      "test_fixed_16_D_PepperDualJumpNoiseXORCipher")) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_16_D_PepperDualJumpNoiseXORCipher failed while unsealing.");
        return;
    }

    if (!CipherGauntlet::Matches(aOriginal, aUnencrypted, sizeof(aOriginal))) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_16_D_PepperDualJumpNoiseXORCipher failed after unseal.");
        printf("Expected: %s\n", PrintExamplesHelper::HexArray(aOriginal, sizeof(aOriginal)).c_str());
        printf("Actual: %s\n", PrintExamplesHelper::HexArray(aUnencrypted, sizeof(aUnencrypted)).c_str());
        return;
    }

}

- (void)test_fixed_16_E_PepperDualJumpNoiseXORCipher {

    // Before Cipher:
    // bit0 10101010  10101010
    // bit1 10101010  10101010
    // bit2 01010101  01010101
    // bit3 01010101  01010101
    // bit4 01010101  01010101
    // bit5 01010101  01010101
    // bit6 10101010  10101010
    // bit7 10101010  10101010
    //
    // After Cipher:
    // bit0 10100111  11011001
    // bit1 10100111  11100100
    // bit2 11111100  10010100
    // bit3 11011100  11011011
    // bit4 10010100  11110111
    // bit5 01101000  11111110
    // bit6 10000111  11100011
    // bit7 10010100  01100010
    //
    // Avalanche:
    // bit0 ....XX.X  .XXX..XX
    // bit1 ....XX.X  .X..XXX.
    // bit2 X.X.X..X  XX.....X
    // bit3 X...X..X  X...XXX.
