                                                    "test_fixed_96_F_PepperDualJumpNoiseXORCipher")) {
        XCTFail("[PepperDualJumpNoiseXORCipher] test_fixed_96_F_PepperDualJumpNoiseXORCipher failed while sealing.");
        return;
    }

    if (!CipherGauntlet::Matches(aExpected, aEncrypted, sizeof(aExpected))) {
